 30→// SearchNotes implements the search_notes tool
 31→func (h *Handler) SearchNotes(ctx context.Context, req *mcp.CallToolRequest, input note.SearchNotesInput) (*mcp.CallToolResult, note.SearchNotesOutput, error) {
 32→	var results []string
 33→	query := input.Query
 34→
 35→	// Try to compile as regex, if it fails, use literal string matching
 36→	var re *regexp.Regexp
 37→	var useRegex bool
 38→	if compiled, err := regexp.Compile("(?i)" + query); err == nil {
 39→		re = compiled
 40→		useRegex = true
 41→	}
 42→
 43→	// Walk through the vault directory
 44→	err := filepath.Walk(h.Vault.Path, func(path string, info os.FileInfo, err error) error {
 45→		if err != nil {
 46→			h.Logger.Debug("skipping path", "path", path, "error", err)
 47→			return nil
 48→		}
 49→
 50→		// Skip directories
 51→		if info.IsDir() {
 52→			// Check if directory is allowed (not hidden)
 53→			allowed, checkErr := h.Vault.IsPathAllowed(path)
 54→			if checkErr != nil || !allowed {
 55→				return filepath.SkipDir
 56→			}
 57→			return nil
 58→		}
 59→
 60→		// Only process markdown files
 61→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
 62→			return nil
 63→		}
 64→
 65→		// Check if file is allowed
 66→		allowed, checkErr := h.Vault.IsPathAllowed(path)
 67→		if checkErr != nil || !allowed {
 68→			return nil
 69→		}
 70→
 71→		// Get filename
 72→		filename := filepath.Base(path)
 73→
 74→		// Match against query
 75→		matched := false
 76→		if useRegex {
 77→			matched = re.MatchString(filename)
 78→		} else {
 79→			matched = strings.Contains(strings.ToLower(filename), strings.ToLower(query))
 80→		}
 81→
 82→		if matched {
 83→			results = append(results, path)
 84→			// Limit results
 85→			if len(results) >= vault.MaxSearchResults {
 86→				return filepath.SkipAll
 87→			}
 88→		}
 89→
 90→		return nil
 91→	})
 92→
 93→	if err != nil {
 94→		return nil, note.SearchNotesOutput{}, fmt.Errorf("failed to search notes: %w", err)
 95→	}
 96→
 97→	output := note.SearchNotesOutput{
 98→		Results: results,
 99→	}
100→
101→	// Create text content for the result
102→	textContent := fmt.Sprintf("Found %d matching notes", len(results))
103→	if len(results) > 0 {
104→		textContent += ":\n" + strings.Join(results, "\n")
105→	}
106→
107→	result := &mcp.CallToolResult{
108→		Content: []mcp.Content{
109→			&mcp.TextContent{
110→				Text: textContent,
111→			},
112→		},
113→	}
114→
115→	return result, output, nil
116→}
