178→// CreateNote implements the create_note tool
179→func (h *Handler) CreateNote(ctx context.Context, req *mcp.CallToolRequest, input note.CreateNoteInput) (*mcp.CallToolResult, note.CreateNoteOutput, error) {
180→	if input.Title == "" {
181→		return nil, note.CreateNoteOutput{}, fmt.Errorf("title is required")
182→	}
183→
184→	slug := note.Slugify(input.Title)
185→	if slug == "" {
186→		return nil, note.CreateNoteOutput{}, fmt.Errorf("title produces an empty slug")
187→	}
188→
189→	today := time.Now().Format("2006-01-02")
190→	filename := today + "_" + slug + ".md"
191→
192→	dir := h.Vault.Path
193→	if input.Folder != "" {
194→		dir = filepath.Join(h.Vault.Path, input.Folder)
195→	}
196→
197→	fullPath := filepath.Join(dir, filename)
198→
199→	allowed, err := h.Vault.IsPathAllowed(fullPath)
200→	if err != nil {
201→		return nil, note.CreateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
202→	}
203→	if !allowed {
204→		return nil, note.CreateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
205→	}
206→
207→	if _, err := os.Stat(fullPath); err == nil {
208→		return nil, note.CreateNoteOutput{}, fmt.Errorf("file already exists: %s", fullPath)
209→	}
210→
211→	if err := os.MkdirAll(dir, 0755); err != nil {
212→		return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to create directory: %w", err)
213→	}
214→
215→	frontmatter := note.GenerateFrontmatter(input.Tags, today, today)
216→
217→	var content strings.Builder
218→	content.WriteString(frontmatter)
219→	content.WriteString("\n# ")
220→	content.WriteString(input.Title)
221→	content.WriteByte('\n')
222→	if input.Content != "" {
223→		content.WriteByte('\n')
224→		content.WriteString(input.Content)
225→		content.WriteByte('\n')
226→	}
227→
228→	if err := os.WriteFile(fullPath, []byte(content.String()), 0644); err != nil {
229→		return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
230→	}
231→
232→	output := note.CreateNoteOutput{Path: fullPath}
233→	result := &mcp.CallToolResult{
234→		Content: []mcp.Content{
235→			&mcp.TextContent{Text: fmt.Sprintf("Created note: %s", fullPath)},
236→		},
237→	}
238→	return result, output, nil
239→}
