241→// UpdateNote implements the update_note tool
242→func (h *Handler) UpdateNote(ctx context.Context, req *mcp.CallToolRequest, input note.UpdateNoteInput) (*mcp.CallToolResult, note.UpdateNoteOutput, error) {
243→	allowed, err := h.Vault.IsPathAllowed(input.Path)
244→	if err != nil {
245→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
246→	}
247→	if !allowed {
248→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
249→	}
250→
251→	if _, err := os.Stat(input.Path); os.IsNotExist(err) {
252→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
253→	}
254→
255→	mode := input.Mode
256→	if mode == "" {
257→		mode = "replace"
258→	}
259→
260→	switch mode {
261→	case "replace":
262→		if err := os.WriteFile(input.Path, []byte(input.Content), 0644); err != nil {
263→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
264→		}
265→	case "append":
266→		existing, err := os.ReadFile(input.Path)
267→		if err != nil {
268→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to read file: %w", err)
269→		}
270→		newContent := string(existing) + "\n\n" + input.Content
271→		if err := os.WriteFile(input.Path, []byte(newContent), 0644); err != nil {
272→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
273→		}
274→	default:
275→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("invalid mode: %s (must be 'replace' or 'append')", mode)
276→	}
277→
278→	output := note.UpdateNoteOutput{Path: input.Path}
279→	result := &mcp.CallToolResult{
280→		Content: []mcp.Content{
281→			&mcp.TextContent{Text: fmt.Sprintf("Updated note (%s): %s", mode, input.Path)},
282→		},
283→	}
284→	return result, output, nil
285→}
