287→// DeleteNote implements the delete_note tool
288→func (h *Handler) DeleteNote(ctx context.Context, req *mcp.CallToolRequest, input note.DeleteNoteInput) (*mcp.CallToolResult, note.DeleteNoteOutput, error) {
289→	if !strings.HasSuffix(strings.ToLower(input.Path), ".md") {
290→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("can only delete .md files")
291→	}
292→
293→	allowed, err := h.Vault.IsPathAllowed(input.Path)
294→	if err != nil {
295→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("path validation error: %w", err)
296→	}
297→	if !allowed {
298→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
299→	}
300→
301→	info, err := os.Stat(input.Path)
302→	if os.IsNotExist(err) {
303→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
304→	}
305→	if err != nil {
306→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("failed to stat file: %w", err)
307→	}
308→	if info.IsDir() {
309→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("cannot delete directories")
310→	}
311→
312→	if err := os.Remove(input.Path); err != nil {
313→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("failed to delete file: %w", err)
314→	}
315→
316→	output := note.DeleteNoteOutput(input)
317→	result := &mcp.CallToolResult{
318→		Content: []mcp.Content{
319→			&mcp.TextContent{Text: fmt.Sprintf("Deleted note: %s", input.Path)},
320→		},
321→	}
322→	return result, output, nil
323→}
