325→// SearchContent implements the search_content tool
326→func (h *Handler) SearchContent(ctx context.Context, req *mcp.CallToolRequest, input note.SearchContentInput) (*mcp.CallToolResult, note.SearchContentOutput, error) {
327→	query := input.Query
328→
329→	var re *regexp.Regexp
330→	var useRegex bool
331→	if compiled, err := regexp.Compile("(?i)" + query); err == nil {
332→		re = compiled
333→		useRegex = true
334→	}
335→
336→	var results []note.ContentMatch
337→
338→	err := filepath.Walk(h.Vault.Path, func(path string, info os.FileInfo, err error) error {
339→		if err != nil {
340→			h.Logger.Debug("skipping path", "path", path, "error", err)
341→			return nil
342→		}
343→
344→		if info.IsDir() {
345→			allowed, checkErr := h.Vault.IsPathAllowed(path)
346→			if checkErr != nil || !allowed {
347→				return filepath.SkipDir
348→			}
349→			return nil
350→		}
351→
352→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
353→			return nil
354→		}
355→
356→		allowed, checkErr := h.Vault.IsPathAllowed(path)
357→		if checkErr != nil || !allowed {
358→			return nil
359→		}
360→
361→		data, err := os.ReadFile(path)
362→		if err != nil {
363→			h.Logger.Debug("skipping unreadable file", "path", path, "error", err)
364→			return nil
365→		}
366→
367→		lines := strings.Split(string(data), "\n")
368→		for lineNum, line := range lines {
369→
370→			matched := false
371→			if useRegex {
372→				matched = re.MatchString(line)
373→			} else {
374→				matched = strings.Contains(strings.ToLower(line), strings.ToLower(query))
375→			}
376→
377→			if matched {
378→				results = append(results, note.ContentMatch{
379→					Path:    path,
380→					Snippet: line,
381→					Line:    lineNum + 1,
382→				})
383→				if len(results) >= vault.MaxSearchResults {
384→					return filepath.SkipAll
385→				}
386→			}
387→		}
388→
389→		return nil
390→	})
391→
392→	if err != nil {
393→		return nil, note.SearchContentOutput{}, fmt.Errorf("failed to search content: %w", err)
394→	}
395→
396→	output := note.SearchContentOutput{Results: results}
397→
398→	textContent := fmt.Sprintf("Found %d matching lines", len(results))
399→	if len(results) > 0 {
400→		var lines []string
401→		for _, m := range results {
402→			lines = append(lines, fmt.Sprintf("%s:%d: %s", m.Path, m.Line, m.Snippet))
403→		}
404→		textContent += ":\n" + strings.Join(lines, "\n")
405→	}
406→
407→	result := &mcp.CallToolResult{
408→		Content: []mcp.Content{
409→			&mcp.TextContent{Text: textContent},
410→		},
411→	}
412→	return result, output, nil
413→}
