415→// GetBacklinks implements the get_backlinks tool
416→func (h *Handler) GetBacklinks(ctx context.Context, req *mcp.CallToolRequest, input note.GetBacklinksInput) (*mcp.CallToolResult, note.GetBacklinksOutput, error) {
417→	if input.NoteName == "" {
418→		return nil, note.GetBacklinksOutput{}, fmt.Errorf("note_name is required")
419→	}
420→
421→	noteName := strings.TrimSuffix(input.NoteName, ".md")
422→	wikilinkRe := regexp.MustCompile(`\[\[([^\]|]+)(?:\|[^\]]+)?\]\]`)
423→
424→	var results []note.Backlink
425→
426→	err := filepath.Walk(h.Vault.Path, func(path string, info os.FileInfo, err error) error {
427→		if err != nil {
428→			h.Logger.Debug("skipping path", "path", path, "error", err)
429→			return nil
430→		}
431→
432→		if info.IsDir() {
433→			allowed, checkErr := h.Vault.IsPathAllowed(path)
434→			if checkErr != nil || !allowed {
435→				return filepath.SkipDir
436→			}
437→			return nil
438→		}
439→
440→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
441→			return nil
442→		}
443→
444→		allowed, checkErr := h.Vault.IsPathAllowed(path)
445→		if checkErr != nil || !allowed {
446→			return nil
447→		}
448→
449→		// Exclude the target note itself
450→		baseName := strings.TrimSuffix(filepath.Base(path), ".md")
451→		if strings.EqualFold(baseName, noteName) {
452→			return nil
453→		}
454→
455→		data, err := os.ReadFile(path)
456→		if err != nil {
457→			h.Logger.Debug("skipping unreadable file", "path", path, "error", err)
458→			return nil
459→		}
460→
461→		lines := strings.Split(string(data), "\n")
462→		for _, line := range lines {
463→			matches := wikilinkRe.FindAllStringSubmatch(line, -1)
464→			for _, match := range matches {
465→				if len(match) >= 2 {
466→					linkTarget := strings.TrimSuffix(match[1], ".md")
467→					if strings.EqualFold(linkTarget, noteName) {
468→						results = append(results, note.Backlink{
469→							Path: path,
470→							Line: line,
471→						})
472→						break // one match per line is enough
473→					}
474→				}
475→			}
476→		}
477→
478→		return nil
479→	})
480→
481→	if err != nil {
482→		return nil, note.GetBacklinksOutput{}, fmt.Errorf("failed to search backlinks: %w", err)
483→	}
484→
485→	output := note.GetBacklinksOutput{Results: results}
486→
487→	textContent := fmt.Sprintf("Found %d backlinks to [[%s]]", len(results), noteName)
488→	if len(results) > 0 {
489→		var lines []string
490→		for _, bl := range results {
491→			lines = append(lines, fmt.Sprintf("%s: %s", bl.Path, bl.Line))
492→		}
493→		textContent += ":\n" + strings.Join(lines, "\n")
494→	}
495→
496→	result := &mcp.CallToolResult{
497→		Content: []mcp.Content{
498→			&mcp.TextContent{Text: textContent},
499→		},
500→	}
501→	return result, output, nil
502→}
