504→// ListTags implements the list_tags tool
505→func (h *Handler) ListTags(ctx context.Context, req *mcp.CallToolRequest, input note.ListTagsInput) (*mcp.CallToolResult, note.ListTagsOutput, error) {
506→	tagCounts := make(map[string]int)
507→
508→	// Regex for inline #tags (not inside code blocks)
509→	inlineTagRe := regexp.MustCompile(`(?:^|\s)#([a-zA-Z][a-zA-Z0-9_/-]*)`)
510→
511→	err := filepath.Walk(h.Vault.Path, func(path string, info os.FileInfo, err error) error {
512→		if err != nil {
513→			h.Logger.Debug("skipping path", "path", path, "error", err)
514→			return nil
515→		}
516→
517→		if info.IsDir() {
518→			allowed, checkErr := h.Vault.IsPathAllowed(path)
519→			if checkErr != nil || !allowed {
520→				return filepath.SkipDir
521→			}
522→			return nil
523→		}
524→
525→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
526→			return nil
527→		}
528→
529→		allowed, checkErr := h.Vault.IsPathAllowed(path)
530→		if checkErr != nil || !allowed {
531→			return nil
532→		}
533→
534→		data, err := os.ReadFile(path)
535→		if err != nil {
536→			h.Logger.Debug("skipping unreadable file", "path", path, "error", err)
537→			return nil
538→		}
539→
540→		content := string(data)
541→
542→		// Parse frontmatter tags
543→		if strings.HasPrefix(content, "---\n") {
544→			endIdx := strings.Index(content[4:], "\n---\n")
545→			if endIdx >= 0 {
546→				frontmatter := content[4 : 4+endIdx]
547→				note.ParseFrontmatterTags(frontmatter, tagCounts)
548→			}
549→		}
550→
551→		// Parse inline #tags (skip code blocks)
552→		lines := strings.Split(content, "\n")
553→		inCodeBlock := false
554→		for _, line := range lines {
555→			if strings.HasPrefix(strings.TrimSpace(line), "```") {
556→				inCodeBlock = !inCodeBlock
557→				continue
558→			}
559→			if inCodeBlock {
560→				continue
561→			}
562→			matches := inlineTagRe.FindAllStringSubmatch(line, -1)
563→			for _, match := range matches {
564→				if len(match) >= 2 {
565→					tagCounts[match[1]]++
566→				}
567→			}
568→		}
569→
570→		return nil
571→	})
572→
573→	if err != nil {
574→		return nil, note.ListTagsOutput{}, fmt.Errorf("failed to list tags: %w", err)
575→	}
576→
577→	// Filter by prefix and sort
578→	var tags []note.TagCount
579→	for tag, count := range tagCounts {
580→		if input.Prefix == "" || strings.HasPrefix(tag, input.Prefix) {
581→			tags = append(tags, note.TagCount{Tag: tag, Count: count})
582→		}
583→	}
584→	sort.Slice(tags, func(i, j int) bool {
585→		return tags[i].Tag < tags[j].Tag
586→	})
587→
588→	output := note.ListTagsOutput{Tags: tags}
589→
590→	textContent := fmt.Sprintf("Found %d unique tags", len(tags))
591→	if len(tags) > 0 {
592→		var lines []string
593→		for _, tc := range tags {
594→			lines = append(lines, fmt.Sprintf("#%s (%d)", tc.Tag, tc.Count))
595→		}
596→		textContent += ":\n" + strings.Join(lines, "\n")
597→	}
598→
599→	result := &mcp.CallToolResult{
600→		Content: []mcp.Content{
601→			&mcp.TextContent{Text: textContent},
602→		},
603→	}
604→	return result, output, nil
605→}
