 28→// TestSearchNotesHandler tests the search_notes tool
 29→func TestSearchNotesHandler(t *testing.T) {
 30→	h, tmpVault := newTestHandler(t)
 31→	defer testutil.CleanupTestVault(t, tmpVault)
 32→
 33→	tests := []struct {
 34→		name            string
 35→		input           note.SearchNotesInput
 36→		wantContains    []string
 37→		wantNotContains []string
 38→		wantCount       int
 39→		wantErr         bool
 40→	}{
 41→		{
 42→			name: "search for 'note' should find multiple files",
 43→			input: note.SearchNotesInput{
 44→				Query: "note",
 45→			},
 46→			wantCount: 3, // note1.md, note2.md, nested-note.md (not .hidden-note.md)
 47→			wantContains: []string{
 48→				"note1.md",
 49→				"note2.md",
 50→				"nested-note.md",
 51→			},
 52→			wantNotContains: []string{
 53→				".hidden-note.md",
 54→			},
 55→		},
 56→		{
 57→			name: "search for 'project' should find project files",
 58→			input: note.SearchNotesInput{
 59→				Query: "project",
 60→			},
 61→			wantCount: 2, // project-plan.md, project-update.md
 62→			wantContains: []string{
 63→				"project-plan.md",
 64→				"project-update.md",
 65→			},
 66→		},
 67→		{
 68→			name: "regex search for files starting with 'note'",
 69→			input: note.SearchNotesInput{
 70→				Query: "^note",
 71→			},
 72→			wantCount: 2, // note1.md, note2.md
 73→			wantContains: []string{
 74→				"note1.md",
 75→				"note2.md",
 76→			},
 77→			wantNotContains: []string{
 78→				"nested-note.md",
 79→			},
 80→		},
 81→		{
 82→			name: "case insensitive search",
 83→			input: note.SearchNotesInput{
 84→				Query: "JOURNAL",
 85→			},
 86→			wantCount: 1, // daily-journal.md
 87→			wantContains: []string{
 88→				"daily-journal.md",
 89→			},
 90→		},
 91→		{
 92→			name: "search with no matches",
 93→			input: note.SearchNotesInput{
 94→				Query: "nonexistent",
 95→			},
 96→			wantCount: 0,
 97→		},
 98→		{
 99→			name: "search should exclude hidden files",
100→			input: note.SearchNotesInput{
101→				Query: "secret",
102→			},
103→			wantCount: 0, // secret.md is in .hidden directory
104→		},
105→		{
106→			name: "search should only return .md files",
107→			input: note.SearchNotesInput{
108→				Query: "txt",
109→			},
110→			wantCount: 0, // not-markdown.txt should not be found
111→		},
112→	}
113→
114→	for _, tt := range tests {
115→		t.Run(tt.name, func(t *testing.T) {
116→			ctx := context.Background()
117→			req := &mcp.CallToolRequest{}
118→
119→			result, output, err := h.SearchNotes(ctx, req, tt.input)
120→			if (err != nil) != tt.wantErr {
121→				t.Errorf("SearchNotes() error = %v, wantErr %v", err, tt.wantErr)
122→				return
123→			}
124→
125→			if err != nil {
126→				return
127→			}
128→
129→			// Check result count
130→			if len(output.Results) != tt.wantCount {
131→				t.Errorf("SearchNotes() got %d results, want %d. Results: %v",
132→					len(output.Results), tt.wantCount, output.Results)
133→			}
134→
135→			// Check that expected files are present
136→			for _, expected := range tt.wantContains {
137→				found := false
138→				for _, r := range output.Results {
139→					if strings.Contains(r, expected) {
140→						found = true
141→						break
142→					}
143→				}
144→				if !found {
145→					t.Errorf("SearchNotes() results missing expected file: %s", expected)
146→				}
147→			}
148→
149→			// Check that unexpected files are not present
150→			for _, notExpected := range tt.wantNotContains {
151→				for _, r := range output.Results {
152→					if strings.Contains(r, notExpected) {
153→						t.Errorf("SearchNotes() results contain unexpected file: %s", notExpected)
154→					}
155→				}
156→			}
157→
158→			// Check that result content is properly formatted
159→			if result == nil {
160→				t.Error("SearchNotes() result is nil")
161→				return
162→			}
163→
164→			if len(result.Content) == 0 {
165→				t.Error("SearchNotes() result content is empty")
166→			}
167→		})
168→	}
169→}
