// Handler holds the vault reference and provides MCP tool handler methods
type Handler struct {
	vault  *vault.Vault
	logger *slog.Logger
}

// New creates a new Handler with the given Vault and Logger
func New(v *vault.Vault, logger *slog.Logger) *Handler {
